// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 deposit, uint256 value) public {
        deposit = bound(deposit, 1, 1e30);
        vm.deal(address(this), deposit);
        (bool ok, ) = address(c).call{value: deposit}("");
        assertTrue(ok);
        value = bound(value, 0, deposit);
        vm.prank(address(this));
        c.withdraw(value);
        assertEq(address(c).balance, deposit - value);
    }
    receive() external payable {}
}
